// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint64 firstNumber, uint64 secondNumber) public {

        vm.prank(DEPOSITOR);
        c.setL1BlockValues(firstNumber, 1, 1, bytes32(0), 1, bytes32(0), 1, 1);

        vm.prank(DEPOSITOR);
        c.setL1BlockValues(secondNumber, 2, 2, bytes32(0), 2, bytes32(0), 2, 2);

        assertTrue(c.number() == secondNumber);
    }
}
